    ok("!! the chosen numbers, to the digit (they are CHOICES: the registration says so)", J(C.CM.decoy) === '{"sl":130,"drift":1.2,"life":40,"count":3,"spacing":6}' && J(C.CM.screen) === '{"r":20,"db":20,"life":30,"count":2,"spacing":10}' && C.CM.interceptor.count === 2 && C.CM.interceptor.spacing === 5 && J(C.CM.interceptor.params) === J({ launchSpeed: 4, cruise: 9, accel: 3, turnRate: 0.4, pitchRate: 0.25, endurance: 20, armDistance: 15, halfCone: 50 * Math.PI / 180 }) && J(C.CM.tactician) === '{"decoySnr":22,"screenSnr":22,"interceptSnr":24,"decoyEvery":6,"screenEvery":10,"interceptEvery":5}' && J(C.CM.ids) === '{"decoy":2000,"torpedo":3000,"interceptor":4000}');
    ok("everything in CM is frozen, down to the interceptor's parameters", [C.CM, C.CM.decoy, C.CM.screen, C.CM.interceptor, C.CM.interceptor.params, C.CM.tactician, C.CM.ids].every(Object.isFrozen));
    ok("the decoy is louder than a boat at full speed (119 dB) and than a launched torpedo (125), so the seeker prefers it: sl 130", C.CM.decoy.sl > K.sourceLevel(4.5) && C.CM.decoy.sl > K.SONAR.torpedoSL);
    ok("!! the kits: none carries nothing, all carries 3 decoys, 2 screens and 2 interceptors, a partial kit carries only what is named; carries() is true exactly when something is carried; the id ranges do not meet the boats' or each other's", J(C.KIT_NONE) === '{"decoy":0,"screen":0,"interceptor":0}' && J(C.KIT_ALL) === '{"decoy":3,"screen":2,"interceptor":2}' && J(C.kitOf({ screen: true })) === '{"decoy":0,"screen":2,"interceptor":0}' && J(C.kitOf()) === J(C.KIT_NONE) && !C.carries(C.KIT_NONE) && C.carries(C.kitOf({ interceptor: true })) && !C.carries(null) && !C.carries(undefined) && C.CM.ids.decoy > 900 && C.CM.ids.decoy < C.CM.ids.torpedo && C.CM.ids.torpedo < C.CM.ids.interceptor && Object.isFrozen(C.KIT_ALL));
    ok("!! the report says the numbers are chosen, not measured, and prints them: both lines to the character (pinned), the 1729 m and 259 m among them", J(C.reportLines()) === J(["[subCountermeasures] THE NUMBERS ARE CHOSEN, NOT MEASURED: decoy 130 dB drifting 1.2 m/s for 40 s (3 a boat, 6 s apart); screen 20 m, 20 dB for 30 s (2 a boat); interceptor 9 m/s for 20 s, 50 deg cone (2 a boat)", "  the tactician releases at heard-torpedo SNR 22 dB (decoy), 22 (screen), 24 (interceptor); the torpedo's own seeker hears a 130 dB decoy from 1729 m and a 2 m/s boat from 259 m"]));
    ok("!! carries() reads each of its three terms: ONE of a single mechanism is enough (decoy 1, screen 1, interceptor 1 alone), all zeros and an empty object are not", C.carries({ decoy: 1, screen: 0, interceptor: 0 }) && C.carries({ decoy: 0, screen: 1, interceptor: 0 }) && C.carries({ decoy: 0, screen: 0, interceptor: 1 }) && !C.carries({ decoy: 0, screen: 0, interceptor: 0 }) && !C.carries({}));
    ok("!! isDecoy at the edges of its range: 1999 no, 2000 yes, 2999 yes, 3000 no (a torpedo's id range starts there), 3005 no, 4000 (an interceptor) no, a boat's 1 and the OGRE's 901 no", (() => { const c = C.createCm({}); return !c.isDecoy(1999) && c.isDecoy(2000) && c.isDecoy(2999) && !c.isDecoy(3000) && !c.isDecoy(3005) && !c.isDecoy(4000) && !c.isDecoy(1) && !c.isDecoy(901); })());
