    const boat = { id: 1, pos: [200, 0, -20], heading: 0, speed: 2 }, decoy = { id: 2000, pos: [250, 40, -20], heading: 0, speed: 1.2, sl: 130 }, quiet = { id: 2001, pos: [250, 40, -20], heading: 0, speed: 1.2, sl: 100 };
